/**
 * Fixed patient-facing wording for emergencies and other non-answers. These are
 * deliberately NOT generated by the model. The wording is a draft that a
 * pharmacist/clinical lead must review and approve before any real use.
 */
import type { EmergencyTriageResult } from '../../src/types/pharmacy.ts';
import type { TriageLevel } from './triage.ts';

export interface Contact { pharmacyName: string; pharmacyPhone: string }

const callPharmacy = (c: Contact) => `${c.pharmacyName} on ${c.pharmacyPhone}`;

export const EMERGENCY_TEXT = (c: Contact) =>
  `**Call 911 now** (or your local emergency number) if you or someone with you has these symptoms. Do not wait for a reply here.\n\n` +
  `- Stay with someone if you can, and keep your medicine bottles close.\n` +
  `- If this might be an overdose or poisoning, call Poison Control on 1-800-222-1222 after calling 911.\n` +
  `- If you are thinking about hurting yourself, call or text 988.\n\n` +
  `I can't assess symptoms. I have sent this message to your pharmacist (${callPharmacy(c)}), but that is not a replacement for emergency care.`;

export const URGENT_TEXT = (c: Contact) =>
  `This sounds like something a health professional should look at **today**. Please call ${callPharmacy(c)} now, or go to urgent care. If it gets worse, or you have trouble breathing, chest pain, or swelling of your face or throat, call 911.\n\n` +
  `Don't take extra doses to make up for anything until you have spoken to a professional. I have sent your message to your pharmacist.`;

export const FORWARDED_TEXT = (c: Contact) =>
  `That's a question for your pharmacist or doctor, not for me. I have sent it to your pharmacist and they can reply here. If you need an answer sooner, call ${callPharmacy(c)}. Please keep taking your medicines as you were told until you have spoken to them.`;

export const UNAVAILABLE_TEXT = (c: Contact) =>
  `I can't answer that right now. Please call ${callPharmacy(c)}. If this is an emergency, call 911. I have passed your question to your pharmacist.`;

export const UNSUPPORTED_TEXT = (c: Contact) =>
  `I couldn't confirm an answer to that from your pharmacist's notes or the drug label, so I won't guess. I have passed your question to your pharmacist. For a faster answer, call ${callPharmacy(c)}.`;

export function triagePayload(level: TriageLevel, c: Contact, text: string): EmergencyTriageResult | null {
  if (level !== 'emergency' && level !== 'urgent') return null;
  return {
    isUrgent: true,
    severity: level === 'emergency' ? 'emergency_911' : 'clinical_call',
    matchedSymptom: '',
    patientInstruction: text.replace(/\*\*/g, '').split('\n\n')[0],
    recommendedClinics: [], // no fictional clinics: real locations would need a real directory
    hotlines: [
      { name: 'Emergency services', phone: '911', badge: 'Life-threatening emergency' },
      { name: 'Poison Control', phone: '1-800-222-1222', badge: 'Poisoning or overdose' },
      { name: 'Crisis line', phone: '988', badge: 'Call or text, 24/7' },
      { name: c.pharmacyName, phone: c.pharmacyPhone, badge: 'Your pharmacy' },
    ],
  };
}
